/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field LineDisc.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModuleLineDisc extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, LineDisc);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    InventTableModule   inventTableModule;

    while select LineDisc from inventTableModule
        group by LineDisc
    {
        if (!ret.in(inventTableModule.LineDisc))
        {
            ret.add(inventTableModule.LineDisc);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, LineDisc));
    qbr.value(queryValue(_value));
}
